SEGS = lambda id,lbl,items: '<div class="ctl"><span class="lbl">%s</span><div class="seg" id="%s" role="group" aria-label="%s">' % (lbl,id,lbl) + ''.join('<button type="button" data-k="%s" aria-pressed="%s">%s</button>' % (k,'true' if i==0 else 'false',t) for i,(k,t) in enumerate(items)) + '</div></div>'

mod('popgrowth','Population growth',
 'A population grows quickly when resources are plentiful and levels off when they run short. The shape of the curve says what is limiting it.',
 ['If resources are unlimited, a population grows <b>exponentially</b>: the growth rate is proportional to the number of individuals, <b>dN/dt = r<sub>max</sub> N</b>, where r is the per capita growth rate (births minus deaths per individual). The curve is J-shaped and gets steeper as N rises. Real populations eventually face limits, so growth follows the <b>logistic model</b>: <b>dN/dt = r<sub>max</sub> N (K − N)/K</b>, with <b>carrying capacity K</b> the largest population the environment can sustain. Growth is fastest at N = K/2 and falls to zero at K.',
  '<b>Density-dependent</b> factors (competition, predation, disease, waste) slow growth more as the population gets crowded. <b>Density-independent</b> factors (fire, storms, freezes) affect a population regardless of its size. Species with high r and many small offspring that get little care are <b>r-selected</b>; species with low r, few offspring and heavy parental care are <b>K-selected</b>. <b>Survivorship curves</b> show how many individuals survive with age: Type I (most live long, die old: humans), Type II (constant death rate: many birds), Type III (high early death: oysters, most plants).'],
 ('populations just grew until something stopped them','that growth rate depends on population size, and limits shape the curve','how to predict and calculate growth and what carrying capacity means','exponential and logistic growth, K, density dependence and survivorship'),
 [('dN/dt = r_max N','exponential growth'),('dN/dt = r_max N (K − N)/K','logistic growth'),('growth is fastest at N = K/2','logistic maximum'),('Type I, II, III survivorship','life history')],
 [lab('pg-lab','Exponential and logistic growth',canvas='pg-canvas',aria='A graph of population size over time for exponential growth or logistic growth with a carrying capacity.',
   seg=('pg-mode','Model',[('exp','exponential'),('log','logistic')]),
   ctl=[('pg-r','Growth rate r (per year)',.05,1,.01,.4),('pg-k','Carrying capacity K',100,2000,50,1000),('pg-n0','Starting population',1,200,1,10)],
   out=[('pg-n','population at year 20','x'),('pg-rate','growth rate dN/dt at the end','a'),('pg-peak','fastest growth at','v')],own=True),
  lab('pg-lab2','Survivorship curves',canvas='pg-canvas2',aria='A graph of the number of survivors against age for the chosen survivorship type.',
   seg=('pg-type','Type',[('1','Type I'),('2','Type II'),('3','Type III')]),
   out=[('pg-ex','examples','x'),('pg-st','strategy','a')],own=True)],
 [('Choose logistic with K = 1000. At what population is growth fastest? <button type="button" class="btn link" data-show=\'' + show(["click","#pg-mode [data-k=log]"],["#pg-k",1000]) + '\'>Set it up for me</button>','','At N = K/2 = 500, where (K − N)/K and N are balanced. Past that, growth slows as resources run out.'),
  ('Switch to exponential. What happens to the curve? <button type="button" class="btn link" data-show=\'' + show(["click","#pg-mode [data-k=exp]"]) + '\'>Set it up for me</button>','','It keeps getting steeper (J-shaped) with no limit, which cannot continue for long in nature.')],
 ('A population of 200 deer in a reserve has r<sub>max</sub> = 0.3 per year and K = 1,000. Find dN/dt at N = 200 and at N = 500.',[
  '<b>Formula.</b> dN/dt = r N (K − N)/K.',
  '<b>At N = 200.</b> 0.3 × 200 × (800/1000) = 48 deer per year.',
  '<b>At N = 500.</b> 0.3 × 500 × (500/1000) = 75 deer per year, the maximum.']),
 ['Saying logistic growth is fastest at K.','Using r as the total growth rather than per capita.','Forgetting density-dependent factors act more strongly at high density.','Thinking carrying capacity never changes.','Confusing survivorship types with growth types.'],
 ('Using the equations',['Substitute the values into the formula from the sheet and keep units (individuals per year). For graph questions: a J-shape means unlimited resources; an S-shape that levels at K means limited resources. Explain the limit with a density-dependent factor (food, space, disease).']),
 [('In logistic growth, the population growth rate is highest when N is about',['K/2','K','0','2K'],0,'Growth rate r N (K − N)/K is largest at N = K/2.')])

mod('community','Communities & species interactions',
 'Species do not live alone. They compete, eat each other, and help each other, and those interactions shape which species live where.',
 ['Interactions are described by their effect on each species. <b>Competition</b> (−/−): two species use the same limiting resource; <b>competitive exclusion</b> says that if their niches are identical, one will eliminate the other, so similar species often partition resources. <b>Predation</b> and <b>herbivory</b> (+/−), <b>parasitism</b> (+/−), <b>mutualism</b> (+/+) and <b>commensalism</b> (+/0). A <b>keystone species</b> (for example the sea star <i>Pisaster</i>) has an effect on community structure much larger than its abundance suggests. Predators and prey often show coupled population cycles.',
  '<b>Species richness</b> is the number of species; <b>species diversity</b> also takes relative abundance into account. <b>Simpson\'s diversity index</b>: <b>D = 1 − Σ(n/N)²</b> (n = number of individuals of one species, N = total). Values near 1 mean high diversity. After a disturbance, <b>ecological succession</b> follows: <b>primary</b> (starts without soil: bare rock after a volcano or glacier) and <b>secondary</b> (soil remains: after a fire or abandoned field). <b>Invasive species</b> can outcompete natives because they lack their natural predators.'],
 ('species just existed side by side','that interactions have signs (+, −, 0) that determine who wins and who thrives','how to quantify diversity and predict community change','competition, predation, symbiosis, keystone species, diversity indices'),
 [('D = 1 − Σ(n/N)²','Simpson\'s index'),('mutualism +/+, commensalism +/0','parasitism and predation +/−'),('competitive exclusion','same niche cannot coexist'),('primary vs secondary succession','soil absent vs present')],
 [lab('cm-lab','Predator and prey',canvas='cm-canvas',aria='A graph of prey and predator numbers over time showing coupled cycles.',
   ctl=[('cm-b','Prey growth rate',.2,1.2,.05,.7),('cm-a','Predation rate',.2,1.5,.05,.6),('cm-d','Predator death rate',.2,1.2,.05,.5)],
   pre='<div class="row"><button type="button" class="btn" id="cm-reset">Restart</button></div>',
   out=[('cm-pn','prey','x'),('cm-qn','predators','a'),('cm-msg','what is happening','')],own=True),
  lab('cm-lab2','Simpson\'s diversity index',canvas='cm-canvas2',aria='Bars showing the number of individuals of four species in a sample and the resulting diversity index.',
   ctl=[('cm-s1','Species A',0,100,1,40),('cm-s2','Species B',0,100,1,30),('cm-s3','Species C',0,100,1,20),('cm-s4','Species D',0,100,1,10)],
   out=[('cm-n','total individuals','x'),('cm-rich','species richness','a'),('cm-dx','Simpson\'s D = 1 − Σ(n/N)²','v')],own=True)],
 [('Run the predator–prey lab as set. Which peaks first? <button type="button" class="btn link" data-show=\'' + show(["click","#cm-reset"]) + '\'>Restart</button>','','Prey peak first; predators follow with a delay because they need time to grow on the extra food, then crash after the prey decline.'),
  ('Make all four species equal (25 each). <button type="button" class="btn link" data-show=\'' + show(["#cm-s1",25],["#cm-s2",25],["#cm-s3",25],["#cm-s4",25]) + '\'>Set it up for me</button>','','D = 1 − 4(0.25²) = 0.75, the maximum for four species: an even community is the most diverse.')],
 ('A sample has 40 individuals of species A, 30 of B, 20 of C and 10 of D. Calculate Simpson\'s diversity index.',[
  '<b>N.</b> 100 individuals.',
  '<b>Σ(n/N)².</b> 0.4² + 0.3² + 0.2² + 0.1² = 0.16 + 0.09 + 0.04 + 0.01 = 0.30.',
  '<b>D.</b> 1 − 0.30 = 0.70.']),
 ['Mixing up richness (how many species) and diversity (also evenness).','Forgetting to square each fraction.','Calling a +/0 relationship mutualism.','Thinking keystone species must be abundant.','Confusing primary succession (no soil) with secondary.'],
 ('Classifying interactions',['Write the effect on each species (+, −, 0). Both +: mutualism. One +, one 0: commensalism. One +, one −: predation, parasitism or herbivory. Both −: competition.']),
 [('A bird eats insects from the skin of a grazing animal without affecting it. This is',['commensalism','mutualism','parasitism','competition'],0,'The bird benefits and the grazer is unaffected: +/0.')])

mod('energyflow','Energy flow & trophic levels',
 'Energy enters ecosystems as sunlight and leaves as heat. Only a small part of it passes from one feeding level to the next.',
 ['<b>Producers</b> (autotrophs) capture light and make organic matter; <b>consumers</b> (heterotrophs) eat it; <b>decomposers</b> break down dead material and return nutrients. Each feeding step is a <b>trophic level</b>. At each step most energy is lost, mainly as heat from cell respiration and in material that is not eaten or digested; typically only about <b>10%</b> of the energy in one level is stored in the next. So energy pyramids narrow quickly and food chains rarely have more than four or five levels.',
  '<b>Gross primary productivity (GPP)</b> is the total energy captured by producers; <b>net primary productivity (NPP) = GPP − R</b> (R is the producers\' respiration) is what is available to consumers. Unlike energy, <b>nutrients cycle</b>. A <b>food web</b> shows many interconnected food chains. Biomass and numbers can also be shown in pyramids, though these can be inverted (for example a pyramid of numbers with one tree and many insects).'],
 ('energy was transferred completely between organisms','that most energy is lost as heat at every level','why top predators are rare and food chains short','trophic levels, the 10% rule, GPP and NPP'),
 [('energy transferred ≈ 10% per level','rest lost as heat and waste'),('NPP = GPP − R','available to consumers'),('energy flows one way; matter cycles','sun → heat'),('producers → primary → secondary → tertiary consumers','trophic levels')],
 [lab('ef-lab','An energy pyramid',canvas='ef-canvas',aria='A pyramid of four trophic levels with the energy in each level.',
   ctl=[('ef-p','Energy captured by producers (kJ)',1000,100000,1000,50000),('ef-e','Transfer efficiency between levels',.05,.3,.01,.1)],
   out=[('ef-1','primary consumers','x'),('ef-2','secondary consumers','a'),('ef-3','tertiary consumers','v'),('ef-4','quaternary consumers','')],own=True),
  lab('ef-lab2','Gross and net primary productivity',canvas='ef-canvas2',aria='A bar showing gross primary productivity split into the producers\' respiration and net primary productivity.',
   ctl=[('ef-g','GPP (kJ per m² per year)',1000,30000,500,12000),('ef-r','Respiration as a fraction of GPP',.1,.8,.01,.4)],
   out=[('ef-npp','NPP','x'),('ef-pct','NPP as a share of GPP','a')],own=True)],
 [('Use 50,000 kJ at producers and 10% efficiency. How much reaches secondary consumers? <button type="button" class="btn link" data-show=\'' + show(["#ef-p",50000],["#ef-e",.1]) + '\'>Set it up for me</button>','','5,000 kJ reaches primary consumers and 500 kJ reaches secondary consumers.'),
  ('Raise the efficiency to 20%. What changes? <button type="button" class="btn link" data-show=\'' + show(["#ef-e",.2]) + '\'>Set it up for me</button>','','Each level holds twice as much as before, so the top levels get far more (4 times at the second step, 8 times at the third), and the food chain could support more levels.')],
 ('A grassland produces 20,000 kJ of NPP per m² per year. If 10% passes to each higher level, how much energy do secondary consumers (level 3) get?',[
  '<b>Producers.</b> 20,000 kJ.',
  '<b>Primary consumers.</b> 10% × 20,000 = 2,000 kJ.',
  '<b>Secondary consumers.</b> 10% × 2,000 = 200 kJ.']),
 ['Saying 90% of energy is "used up". It is lost mainly as heat and in unconsumed or undigested matter.','Thinking energy cycles (it does not).','Starting the pyramid with the wrong level.','Mixing GPP and NPP.','Saying decomposers are not part of energy flow.'],
 ('Explaining the limit on chain length',['Energy declines by about 90% per level, so after four or five levels there is too little left to support a population. Mention heat loss from cellular respiration and uneaten matter.']),
 [('If 10,000 kJ is in producers, about how much is available to tertiary consumers (10% efficiency)?',['10 kJ','100 kJ','1,000 kJ','1 kJ'],0,'10,000 → 1,000 → 100 → 10 kJ.')])

mod('cycles','Biogeochemical cycles',
 'Atoms are reused over and over. Carbon, nitrogen, phosphorus and water move between living things, air, water and rock.',
 ['<b>Carbon cycle</b>: producers fix CO₂ into organic molecules by photosynthesis; all organisms release CO₂ by respiration; decomposers return carbon from dead matter; burning fossil fuels and wood adds CO₂ to the atmosphere; the ocean exchanges CO₂ with the air. <b>Nitrogen cycle</b>: bacteria perform <b>nitrogen fixation</b> (N₂ → NH₃/NH₄⁺), <b>nitrification</b> (NH₄⁺ → NO₂⁻ → NO₃⁻, the form plants take up), <b>assimilation</b> into proteins and nucleic acids, <b>ammonification</b> by decomposers and <b>denitrification</b> (NO₃⁻ → N₂ back to the air). <b>Phosphorus</b> has no gas phase: it cycles through rock, soil, water and organisms. <b>Water cycle</b>: evaporation, transpiration, condensation, precipitation, runoff.',
  'Human activities change the cycles. Burning fossil fuels raises atmospheric CO₂ (about 420 ppm in recent years, up from about 280 ppm before the industrial era), which enhances the greenhouse effect and warms the climate; some CO₂ dissolves in the oceans and causes <b>ocean acidification</b>. Fertilizer runoff adds nitrogen and phosphorus to waters (see eutrophication).'],
 ('matter was used once and gone','that elements cycle between reservoirs through living and non-living steps','how human activity shifts those cycles','carbon, nitrogen, phosphorus and water cycles'),
 [('photosynthesis: CO₂ → organic carbon','respiration, combustion: organic carbon → CO₂'),('N₂ → NH₃ → NO₃⁻ → N₂','fixation, nitrification, denitrification'),('phosphorus: no atmospheric phase','weathering, uptake, decomposition'),('1 ppm CO₂ ≈ 2.1 GtC; about half stays in the air','approximate')],
 [lab('cy-lab','Follow the atoms',canvas='cy-canvas',aria='A diagram of the chosen cycle with boxes for reservoirs and arrows for the processes that move atoms between them.',
   seg=('cy-sel','Cycle',[('c','carbon'),('n','nitrogen'),('p','phosphorus'),('w','water')]),
   out=[('cy-key','key organisms or process','x'),('cy-human','human effect','a')],own=True),
  lab('cy-lab2','Atmospheric CO₂ from emissions',canvas='cy-canvas2',aria='A graph of atmospheric carbon dioxide concentration over time for the chosen emission rate.',
   ctl=[('cy-em','Emissions (billion tonnes of carbon per year)',0,15,.5,10),('cy-yr','Years from now',0,100,1,30)],
   out=[('cy-co2','atmospheric CO₂','x'),('cy-inc','increase from today','a')],own=True)],
 [('Choose the nitrogen cycle. Which step makes nitrate that plants can use? <button type="button" class="btn link" data-show=\'' + show(["click","#cy-sel [data-k=n]"]) + '\'>Set it up for me</button>','','Nitrification by soil bacteria: ammonium → nitrite → nitrate.'),
  ('Set emissions to 10 GtC per year and look 30 years ahead. <button type="button" class="btn link" data-show=\'' + show(["#cy-em",10],["#cy-yr",30]) + '\'>Set it up for me</button>','','About 63 ppm higher (10 × 0.45 / 2.13 ≈ 2.1 ppm per year): a simple model for a rough idea.')],
 ('Explain how nitrogen from a dead plant becomes available to a living plant.',[
  '<b>Decomposers.</b> Bacteria and fungi break down the dead plant and release ammonium (ammonification).',
  '<b>Nitrifying bacteria.</b> Convert ammonium to nitrite and then nitrate (nitrification).',
  '<b>Uptake.</b> The living plant takes up nitrate (or ammonium) through its roots and assimilates it into amino acids and nucleotides.']),
 ['Saying plants take up N₂ from the air.','Mixing up nitrification and denitrification.','Thinking phosphorus has an atmospheric phase.','Saying decomposers are not part of the carbon cycle.','Believing atmospheric CO₂ rises only because of deforestation (fossil fuels are the largest source).'],
 ('Cycle questions',['Draw the reservoirs and label each arrow with a process and the organisms involved. For human effects, say which flux increased and what that changed in the reservoirs.']),
 [('Which process returns nitrogen gas to the atmosphere?',['denitrification','nitrification','nitrogen fixation','ammonification'],0,'Denitrifying bacteria convert nitrate to N₂ in low-oxygen soils.')])

mod('disruption','Human impact & ecosystem disruption',
 'Ecosystems can absorb some disturbance, but human activity often pushes them past what they can recover from.',
 ['<b>Eutrophication</b>: fertilizer or sewage adds nitrogen and phosphorus to a lake; algae bloom; when they die, decomposers use up the oxygen, and fish and other animals suffocate. <b>Biomagnification</b>: toxins that are fat-soluble or not broken down (DDT, mercury, PCBs) become more concentrated at each trophic level, so top predators are most affected. <b>Invasive species</b> can outcompete natives. <b>Habitat fragmentation</b> splits populations and reduces gene flow. <b>Climate change</b> shifts ranges and timing of life cycles, and <b>ocean acidification</b> harms organisms with calcium carbonate shells.',
  'Biodiversity matters for ecosystem stability and services. Ecosystems with more species and more genetic diversity tend to be more <b>resilient</b>. Conservation tools include protected areas and corridors, restoring habitat, reducing pollution, controlling invasives and sustainable harvesting. <b>Keystone species</b> and <b>indicator species</b> help monitor ecosystem health.'],
 ('pollution just spreads out and disappears','that some pollutants accumulate along food chains and some nutrients overload ecosystems','why top predators and small populations are most vulnerable','eutrophication, biomagnification, invasive species and climate impacts'),
 [('eutrophication: nutrients → algae → low O₂','dead zones'),('biomagnification: concentration × factor per level','top predators highest'),('habitat fragmentation → small isolated populations','less gene flow'),('CO₂ ↑ → warming and ocean acidification','climate impacts')],
 [lab('dp-lab','Biomagnification',canvas='dp-canvas2',aria='Bars on a logarithmic scale showing the concentration of a pollutant at each level of a food chain.',
   ctl=[('dp-w','Concentration in water (ppb)',.001,1,.001,.01),('dp-f','Concentration factor per level',2,20,1,10)],
   out=[('dp-1','algae','x'),('dp-2','zooplankton','a'),('dp-3','small fish','v'),('dp-4','large fish','a'),('dp-5','fish-eating bird','x')],own=True),
  stagelab('dp-lab2','A lake turns green',canvas='dp-canvas',aria='Stages of eutrophication in a lake: nutrient input, algal bloom, decomposition and oxygen loss, then fish die.',p='eu',n=4)],
 [('Set the water at 0.01 ppb and a factor of 10. How concentrated is it in the bird? <button type="button" class="btn link" data-show=\'' + show(["#dp-w",.01],["#dp-f",10]) + '\'>Set it up for me</button>','','0.01 × 10⁵ = 1,000 ppb: a hundred thousand times higher than in the water.'),
  ('Go to the stage when algae die. Where does the oxygen go? <button type="button" class="btn link" data-show=\'' + show(["#eu-st",2]) + '\'>Set it up for me</button>','','Decomposers (bacteria) use it up as they break down the dead algae by aerobic respiration.')],
 ('A pesticide is 0.5 ppb in lake water. Each trophic level concentrates it 10-fold. Algae take it up from water and are eaten by zooplankton, then small fish, then a heron. What is the concentration in the heron?',[
  '<b>Algae.</b> 0.5 × 10 = 5 ppb.',
  '<b>Zooplankton.</b> 50 ppb.',
  '<b>Small fish.</b> 500 ppb.',
  '<b>Heron.</b> 5,000 ppb.']),
 ['Saying toxins are diluted as they go up the food chain.','Mixing up eutrophication (nutrient overload) and biomagnification (toxin accumulation).','Saying algae blooms add oxygen to the lake when they die.','Thinking invasive species are always harmful in their home range.','Forgetting that fragmentation reduces gene flow.'],
 ('Explaining effects',['Name the human action, the first thing it changes in the ecosystem, the chain of consequences, and the final effect on populations (use the trophic levels and decomposers).']),
 [('A chemical that is not broken down is found at the highest concentration in',['top predators','producers','decomposers only','the soil only'],0,'Biomagnification concentrates persistent toxins at higher trophic levels.')])
